INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (339, 30, 'tr', 'Duş Bataryası 1654-001', 'Lavabo Musluğu, Ankastre\nKaplama: Krom\nBatarya Tipi: Tek Kollu Batarya\nMontaj Şekli: Ankastre', 'Batarya gövdesi en yüksek kalitede pirinçten üretilmiştir\nBatarya, akış perlátorü ile donatılmıştır\nKolay kireç temizliği için silikon perlátor\nAnkastre montaj, banyonun estetiğini korur\nSu tüketimini azaltmaya olanak veren Z debi sınıfı (4-9 l/dk)\nGüzellik ve uyum dolu tasarım\nRenk çeşitliliği birçok uyarlama imkânı sunar\nKalitesi laboratuvar testleriyle onaylanmış en iyi malzemeler\nTüm renk armatürler için temizlik maddesi mevcuttur');
INSERT INTO `seo_meta` (`id`, `product_id`, `locale`, `meta_title`, `meta_description`, `og_title`, `og_description`, `canonical_url`, `created_at`, `updated_at`) VALUES (312, 30, 'tr', 'Duş Bataryası 1654-001 | LUFLY', 'Lavabo Musluğu, Ankastre\nKaplama: Krom\nBatarya Tipi: Tek Kollu Batarya\nMontaj Şekli: Ankastre', NULL, NULL, NULL, '2026-09-20 02:57:46', '2026-09-20 02:57:46');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (340, 30, 'cs', 'Sprchová baterie 1654-001', 'Umyvadlová baterie, podomítková\nPovrch: chrom\nTyp baterie: jednopáková baterie\nZpůsob instalace: podomítková', 'Těleso baterie je vyrobeno z nejkvalitnější mosazi\nBaterie je vybavena perlátorem\nSilikonový perlátor pro snadné odstranění vodního kamene\nPodomítková instalace zachovává estetiku koupelny\nPrůtoková třída Z (4-9 l/min) umožňující snížení spotřeby vody\nDesign plný krásy a harmonie\nRozmanitost barev nabízí mnoho možností aranžování\nPouze ty nejlepší materiály, jejichž kvalita byla potvrzena laboratorními testy\nČisticí prostředek pro baterie ve všech barvách k dispozici');
INSERT INTO `seo_meta` (`id`, `product_id`, `locale`, `meta_title`, `meta_description`, `og_title`, `og_description`, `canonical_url`, `created_at`, `updated_at`) VALUES (313, 30, 'cs', 'Sprchová baterie 1654-001 | LUFLY', 'Umyvadlová baterie, podomítková\nPovrch: chrom\nTyp baterie: jednopáková baterie\nZpůsob instalace: podomítková', NULL, NULL, NULL, '2026-09-20 02:57:46', '2026-09-20 02:57:46');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (341, 31, 'tr', 'Lavabo Bataryası 1654-002', '• 35 mm seramik kartuş\n• Click-clack sifon tapası, yuvarlak, taşmalı\n• Debi sınıfı Z - 4-9 l/dk\n• Akustik grup I - 20 dB\'ye kadar\n• 45 cm besleme hortumları', 'Renk kromdur\nBatarya tipi tek kollu batarya\nTezgâh üstü montaj şekli\nDebi sınıfı [l/dk.] Z - 4-9 l/dk\nAkustik grup [dB] I (x ≤ 20)\nTapa sete şu şekilde dahildir\nSeramik kartuş ölçüsü 35 mm\'dir\nEco-click kartuş evet\nÇıkış ucu tipi sabittir\nBatarya çıkış mesafesi [mm] 128\nMalzeme Pirinç\nPerlátor tipi döner, düz\nPerlátor ölçüsü M24\nUzunluk [mm] 450\nBağlantı dişi M10\ntip click\nTaşmalı tip');
INSERT INTO `seo_meta` (`id`, `product_id`, `locale`, `meta_title`, `meta_description`, `og_title`, `og_description`, `canonical_url`, `created_at`, `updated_at`) VALUES (314, 31, 'tr', 'Lavabo Bataryası 1654-002 | LUFLY', '• 35 mm seramik kartuş\n• Click-clack sifon tapası, yuvarlak, taşmalı\n• Debi sınıfı Z - 4-9 l/dk\n• Akustik grup I - 20 dB\'ye kadar\n• 45 cm besleme hortumları', NULL, NULL, NULL, '2026-09-20 02:57:46', '2026-09-20 02:57:46');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (342, 31, 'cs', 'Umyvadlová baterie 1654-002', '• keramická kartuše 35 mm\n• Zátka click-clack, kulatá, s přepadem\n• Průtoková třída Z - 4-9 l/min\n• Akustická skupina I - do 20 dB\n• přívodní hadice 45 cm', 'Barva je chrom\nTyp baterie jednopáková baterie\nStojící způsob instalace\nPrůtoková třída [l/min.] Z - 4-9 l/min\nAkustická skupina [dB] I (x ≤ 20)\nZátka je součástí sady následovně\nVelikost keramické kartuše je 35 mm\nKartuše eco-click ano\nTyp výtoku je pevný\nDosah výtoku baterie [mm] 128\nMateriál mosaz\nTyp perlátoru je otočný, plochý\nVelikost perlátoru M24\nDélka [mm] 450\nPřipojovací závit M10\ntyp click\nTyp s přepadem');
INSERT INTO `seo_meta` (`id`, `product_id`, `locale`, `meta_title`, `meta_description`, `og_title`, `og_description`, `canonical_url`, `created_at`, `updated_at`) VALUES (315, 31, 'cs', 'Umyvadlová baterie 1654-002 | LUFLY', '• keramická kartuše 35 mm\n• Zátka click-clack, kulatá, s přepadem\n• Průtoková třída Z - 4-9 l/min\n• Akustická skupina I - do 20 dB\n• přívodní hadice 45 cm', NULL, NULL, NULL, '2026-09-20 02:57:46', '2026-09-20 02:57:46');
INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (343, 32, 'tr', 'Duş Bataryası 1654-003', 'Kaplama: krom\nBatarya tipi: tek kollu batarya\nMontaj şekli: ankastre', 'Kalitesi laboratuvar testleriyle onaylanmış en iyi malzemeler\nBatarya, akış perlátorü ile donatılmıştır\nAnkastre montaj, banyonun estetiğini korur\nTüm renk armatürler için temizlik maddesi mevcuttur');
