INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (371, 46, 'tr', 'El Kurutma Makinesi 1300-SUR66', 'El Kurutma Makinesi', 'El Kurutma Makinesi\nPaslanmaz çelik gövdeli modern ve dayanıklı bir el kurutma makinesidir. Oda sıcaklığına uyum sağlayarak yalnızca sıcaklık 25°C\'nin altına düştüğünde ısı ekleyen akıllı ısıtma sistemi sayesinde enerji tasarrufu sağlar.\nTeknik Özellikler:\n• Voltaj: 220–240V\n• Güç: 800–1650W\n• Hava Hızı: 95 m/s\n• Motor Deviri: 21.000\n• Ağırlık: 12.5 kg\n• Ölçüler: 300 x 730 x 222 mm\n• Gürültü: 2 metrede 72 dB\n• Su Sıçraması Koruması: IPX4\n• Otomatik Kapanma: 30 saniye');
