INSERT INTO `product_translations` (`id`, `product_id`, `locale`, `name`, `short_description`, `description`) VALUES (372, 46, 'cs', 'Vysoušeč rukou 1300-SUR66', 'Vysoušeč rukou', 'Vysoušeč rukou\nModerní a odolný vysoušeč rukou s tělesem z nerezové oceli. Inteligentní topný systém šetří energii tím, že se přizpůsobuje pokojové teplotě a teplo přidává pouze tehdy, když klesne pod 25 °C.\nTechnické parametry:\n• Napětí: 220–240V\n• Příkon: 800–1650W\n• Rychlost vzduchu: 95 m/s\n• Otáčky motoru: 21 000\n• Hmotnost: 12,5 kg\n• Rozměry: 300 x 730 x 222 mm\n• Hlučnost: 72 dB na 2 metry\n• Ochrana proti stříkající vodě: IPX4\n• Automatické vypnutí: 30 sekund');
